terms.code:
struct Dog {
    func speak() { print("Woof") }
}
Dog().speak()  // struct: static dispatch

class Animal {
    func speak() { print("...") } }
class Cat: Animal {
    override func speak() { print("Meow") } }
let pet: Animal = Cat()
pet.speak()

protocol Speaker { func speak() }
struct Duck: Speaker {
    func speak() { print("Quack") } }
let s: any Speaker = Duck()
s.speak()  // found in Duck's witness table

